param([switch]$LivePrometheus,[string]$PrometheusUrl,[string]$ExpectedJob,[string]$ExpectedInstance,[switch]$ExpectDown)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$root=Split-Path -Parent $PSScriptRoot;$e=Join-Path $root 'evidence\L4-failure-recovery\S036-prometheus-target-down-validation'
$p=@{Runbook=Join-Path $root 'runbooks\prometheus-target-down-validation.md';Commands=Join-Path $root 'runbooks\prometheus-target-down-commands.example.md';Alert=Join-Path $root 'observability\prometheus\prometheus-target-down-alerts.example.yml';Criteria=Join-Path $root 'observability\prometheus\prometheus-target-down-criteria.example.md';Matrix=Join-Path $root 'observability\prometheus\prometheus-target-down-response-matrix.example.md';PreTargets=Join-Path $e 'logs\pre-failure-prometheus-targets.sample.json';PreUp=Join-Path $e 'logs\pre-failure-up-query.sample.json';Injection=Join-Path $e 'logs\target-down-injection-event.sample.txt';DownTargets=Join-Path $e 'logs\target-down-prometheus-targets.sample.json';DownUp=Join-Path $e 'logs\target-down-up-query.sample.json';DownAlerts=Join-Path $e 'logs\target-down-alerts.sample.json';Recovery=Join-Path $e 'logs\target-recovery-event.sample.txt';PostTargets=Join-Path $e 'logs\post-recovery-prometheus-targets.sample.json';PostUp=Join-Path $e 'logs\post-recovery-up-query.sample.json';PostAlerts=Join-Path $e 'logs\post-recovery-alerts-cleared.sample.json'}
$log=Join-Path $e 'logs\prometheus-target-down-validation.log';$summary=Join-Path $e 'configs\prometheus-target-down-summary.md';New-Item -ItemType Directory -Force -Path (Split-Path $log),(Split-Path $summary)|Out-Null
$rs=[System.Collections.Generic.List[object]]::new();$ls=[System.Collections.Generic.List[string]]::new();$fail=0;$warn=0
function Add-R([string]$Id,[string]$Name,[string]$Result,[string]$Detail){if($Result-eq'FAIL'){$script:fail++};if($Result-eq'WARN'){$script:warn++};$x="[$Result] $Id ${Name}: $Detail";Write-Host $x;$script:ls.Add($x)|Out-Null;$script:rs.Add([pscustomobject]@{Id=$Id;Name=$Name;Result=$Result;Detail=$Detail})|Out-Null};function T([string]$x){if(Test-Path $x -PathType Leaf){Get-Content $x -Raw}else{''}}
$missing=@($p.Values|Where-Object{-not(Test-Path $_ -PathType Leaf)});Add-R V001 'Required artifacts' $(if($missing.Count-eq 0){'PASS'}else{'FAIL'}) 'Five baselines and ten samples are required.';$c=@{};foreach($k in $p.Keys){$c[$k]=T $p[$k]};$all=($c.Values)-join"`n"
$terms=@('<prometheus-server>','<scrape-job-name>','<target-instance-placeholder>','<exporter-name-placeholder>','<failure-method-placeholder>','<target-down-duration-threshold>','<recovery-time-threshold-seconds>','<evidence-path>','Static','LivePrometheus');Add-R V002 'Runbook workflow and modes' $(if(@($terms|Where-Object{$c.Runbook-notmatch[regex]::Escape($_)}).Count-eq 0){'PASS'}else{'FAIL'}) 'Workflow placeholders and modes are required.'
$alert=$c.Alert-match'alert:\s*SNSDTargetDownPlaceholder'-and$c.Alert-match'up\{job="<scrape-job-name-placeholder>"\}\s*==\s*0'-and$c.Alert-match'scenario:\s*S036'-and$c.Alert-match'for:\s*2m';Add-R V003 'Alert rule placeholder' $(if($alert){'PASS'}else{'FAIL'}) 'Target-down expression, duration, and S036 label are required.';$phases=@('Pre-failure target discovery','Pre-failure target UP state','Manual target-down injection','Prometheus target DOWN detection','up metric equals 0','Alert rule evaluation placeholder','Alert firing placeholder','Recovery action placeholder','Post-recovery target UP state','Alert cleared placeholder','Recovery time threshold');Add-R V004 'Criteria matrix' $(if(@($phases|Where-Object{$c.Criteria-notmatch[regex]::Escape($_)}).Count-eq 0){'PASS'}else{'FAIL'}) 'All eleven phases are required.';$matrix=$c.Matrix-match'target health up'-and$c.Matrix-match'target health down'-and$c.Matrix-match'up = 1'-and$c.Matrix-match'up = 0'-and$c.Matrix-match'alert firing'-and$c.Matrix-match'alert resolved';Add-R V005 'Response matrix' $(if($matrix){'PASS'}else{'FAIL'}) 'Required target/up/alert signals are required.'
$pre=$c.PreTargets-match'"health":"up"'-and$c.PreUp-match'"value":\["<timestamp-placeholder>","1"\]';Add-R V006 'Pre-failure target UP evidence' $(if($pre){'PASS'}else{'FAIL'}) 'Target health up and up value 1 are required.';$injection=$c.Injection-match'MANUAL FAULT INJECTION SAMPLE'-and$c.Injection-match'Execution_By_Validator:\s*false';Add-R V007 'Manual target-down injection' $(if($injection){'PASS'}else{'FAIL'}) 'Stop event must be manual-only.';$down=$c.DownTargets-match'"health":"down"'-and$c.DownTargets-match'<scrape-error-placeholder>'-and$c.DownUp-match'"value":\["<timestamp-placeholder>","0"\]';Add-R V008 'Target DOWN and up=0 evidence' $(if($down){'PASS'}else{'FAIL'}) 'Down health, scrape error, and up value 0 are required.';$firing=$c.DownAlerts-match'SNSDTargetDownPlaceholder'-and$c.DownAlerts-match'"state":"firing"';Add-R V009 'Alert firing evidence' $(if($firing){'PASS'}else{'FAIL'}) 'Target-down alert must be firing.'
$recovery=$c.Recovery-match'MANUAL RECOVERY ACTION SAMPLE'-and$c.Recovery-match'Execution_By_Validator:\s*false';Add-R V010 'Manual recovery evidence' $(if($recovery){'PASS'}else{'FAIL'}) 'Start event must be manual-only.';$post=$c.PostTargets-match'"health":"up"'-and$c.PostUp-match'"value":\["<timestamp-placeholder>","1"\]';Add-R V011 'Post-recovery target UP evidence' $(if($post){'PASS'}else{'FAIL'}) 'Target health up and up value 1 are required.';$cleared=$c.PostAlerts-match'(?i)"state":"(?:inactive|resolved[^" ]*|cleared[^" ]*)"'-and$c.PostAlerts-notmatch'"state":"firing"';Add-R V012 'Alert cleared evidence' $(if($cleared){'PASS'}else{'FAIL'}) 'Alert must be inactive/resolved/cleared.'
$manual=$c.Commands-match'MANUAL FAULT INJECTION ONLY'-and$c.Commands-match'MANUAL RECOVERY ACTION ONLY'-and$c.Commands-match'never executes';Add-R V013 'Manual command boundary' $(if($manual){'PASS'}else{'FAIL'}) 'Exporter stop/start must be manual-only.';$elapsed=[regex]::Match($c.Injection,'(?im)^Recovery_Elapsed_Seconds:\s*(\d+(?:\.\d+)?)\s*$');Add-R V014 'Recovery timing' $(if($elapsed.Success){'PASS'}else{'WARN'}) 'Unmeasured time leaves threshold compliance unproven.'
$badPost=$c.PostTargets-match'"health":"down"'-or$c.PostUp-match'"value":\["<timestamp-placeholder>","0"\]'-or$c.PostAlerts-match'"state":"firing"';Add-R V015 'Recovered-state failure indicators' $(if(-not$badPost){'PASS'}else{'FAIL'}) 'No down/up=0/firing signal may remain.';$ip=[regex]::Matches($all,'(?<![A-Za-z0-9<])(?:\d{1,3}\.){3}\d{1,3}(?![A-Za-z0-9>])').Count;$url=[regex]::Matches($all,'(?i)https?://(?!<)[^\s"`]+').Count;$domain=[regex]::Matches($all,'(?i)(?<![A-Za-z0-9<.-])(?:[a-z0-9-]+\.)+[a-z]{2,}(?![A-Za-z0-9>.-])').Count;$secret=$all-match'(?im)^\s*(?:token|password|secret|authorization|cookie|webhook)\s*[:=]\s*(?!["'']?<)\S+'-or$all-match'-----BEGIN .*PRIVATE KEY-----';$safe=$ip-eq 0-and$url-eq 0-and$domain-eq 0-and-not$secret;Add-R V016 'Endpoint and secret safety' $(if($safe){'PASS'}else{'FAIL'}) 'No real URL/domain/address, credential, webhook, key, or secret may exist.'
$script=Get-Content $PSCommandPath -Raw;$unsafe=$script-match'(?im)^\s*(?:systemctl|service|promtool|kubectl|docker|ansible-playbook)\b';Add-R V017 'Execution safety boundary' $(if(-not$unsafe){'PASS'}else{'FAIL'}) 'No exporter/Prometheus start, stop, reload, rule change, or other mutation is allowed.'
$mode=if($LivePrometheus){'LivePrometheus'}else{'Static'};if($LivePrometheus){$live='PASS';$detail='Read-only API state summarized.';if([string]::IsNullOrWhiteSpace($PrometheusUrl)){$live='FAIL';$detail='PrometheusUrl is required.'}else{try{$targets=Invoke-RestMethod -Uri "$PrometheusUrl/api/v1/targets" -Method Get -TimeoutSec 10;$up=Invoke-RestMethod -Uri "$PrometheusUrl/api/v1/query?query=up" -Method Get -TimeoutSec 10;$alerts=Invoke-RestMethod -Uri "$PrometheusUrl/api/v1/alerts" -Method Get -TimeoutSec 10;$targetRows=@($targets.data.activeTargets);if($ExpectedJob){$targetRows=@($targetRows|Where-Object{$_.labels.job-eq$ExpectedJob})};if($ExpectedInstance){$targetRows=@($targetRows|Where-Object{$_.labels.instance-eq$ExpectedInstance})};if($ExpectDown-and@($targetRows|Where-Object{$_.health-eq'down'}).Count-eq 0){$live='FAIL';$detail='Expected target-down state was not observed.'}elseif(-not$ExpectDown-and@($targetRows|Where-Object{$_.health-eq'down'}).Count-gt 0){$live='WARN';$detail='API reachable, but one or more selected targets are down.'}}catch{$live='FAIL';$detail='Read-only API query failed; raw response was not stored.'}};Add-R V018 'LivePrometheus read-only state' $live $detail}
$ts=(Get-Date).ToString('yyyy-MM-ddTHH:mm:ssK');$overall=if($fail-eq 0){'PASS'}else{'FAIL'};$final="[$overall] Prometheus target down ($mode): $fail critical failure(s), $warn warning(s).";Write-Host $final;@('SNSD Multi-Cloud Ops - S036 Prometheus Target Down Validation',"Generated: $ts","Validation mode: $mode",'')+@($ls)+@('', $final,'No exporter/Prometheus/rule mutation, credential, raw API response, URL, or sensitive target detail was stored.')|Set-Content $log -Encoding UTF8
$out=@('# Prometheus Target Down Summary','', '- Scenario: S036-prometheus-target-down-validation',"- Generated: $ts","- Validation mode: **$mode**","- Required file check result: **$(if($missing.Count-eq 0){'PASS'}else{'FAIL'})**","- Alert rule placeholder result: **$(if($alert){'PASS'}else{'FAIL'})**","- Pre-failure UP result: **$(if($pre){'PASS'}else{'FAIL'})**","- Manual target-down result: **$(if($injection){'PASS'}else{'FAIL'})**","- Target DOWN/up=0 result: **$(if($down){'PASS'}else{'FAIL'})**","- Alert firing result: **$(if($firing){'PASS'}else{'FAIL'})**","- Manual recovery result: **$(if($recovery){'PASS'}else{'FAIL'})**","- Post-recovery UP result: **$(if($post){'PASS'}else{'FAIL'})**","- Alert cleared result: **$(if($cleared){'PASS'}else{'FAIL'})**","- Secret-safety result: **$(if($safe){'PASS'}else{'FAIL'})**","- Final judgment: **$overall**",'','| Check ID | Check | Result | Detail |','|---|---|---|---|');foreach($r in $rs){$out+="| $($r.Id) | $($r.Name) | $($r.Result) | $($r.Detail) |"};$out|Set-Content $summary -Encoding UTF8;if($fail-gt 0){exit 1};exit 0
